WITH with_windows AS (SELECT *, SUM(shipping_fee) OVER (PARTITION BY channel, status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_shipping_fee, AVG(shipping_fee) OVER (PARTITION BY channel, status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_shipping_fee, COUNT(shipping_fee) OVER (PARTITION BY channel, status ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_shipping_fee, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY order_date DESC, id) AS seq_no FROM orders) SELECT s.id, s.customer_id, s.store_id, s.order_date, s.channel, s.amount, s.discount, s.shipping_fee, s.running_avg_shipping_fee, (SELECT MIN(t2.discount) FROM orders t2 WHERE t2.store_id = s.store_id) AS min_order_discount FROM with_windows s ORDER BY shipping_fee DESC;
